let S, TH, N = 11;
const PENS = ["orange", "pink", "deeppink"];

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("overlapping circles of different colors formed by lines ");
	S = max(width, height);
	TH = S/N;
	strokeWeight(TH/2);
}

function draw() {
	blendMode(BLEND)
	background(4, 4, 12);
	blendMode(ADD)
	translate(width/2, height/2);

	let a = frameCount/123; // random(TAU);
	for (let i = 0; i < PENS.length; i++) {
		push();
		const clr = color(PENS[i])
		clr.setAlpha(160);
		stroke(clr);
		rotate(a);
		drawForm();
		pop();

		a += noise(i/321, frameCount/321) * TWO_PI / PENS.length;
	}

	// // noLoop() removed for animation
}

function drawForm() {
	let xs = -TH * N / 2;
	let xe = xs + S;
	let x = xs + TH/2;
	for (let i = 0; i < N; i++) {
		const h = S/2-abs(x);
		const y = sqrt(S*h-h*h); // Kreissehne
		line(x, -y, x, y);
		x += TH;
	}
}
